use std::str::FromStr;

use midnight_did::did::MidnightDid;
use midnight_did::dlt::{ContractState, ContractStateDeserializer};

const CLI_PATH: &str = "midnight-did-serde-js";

const DID: &str = "did:midnight:undeployed:0200581ac6d2f01668c58dacccfc8cc7eadac84cd8c3ddfee8703dbe994928db5ba1";
const CONTRACT_STATE: &str = "";

#[test]
fn test_midnight_serde_rs() {
    use midnight_did_serde::DefaultContractStateDeserializer;

    let did = MidnightDid::from_str(DID).unwrap();
    let state = ContractState::from_str(CONTRACT_STATE).unwrap();
    let deserializer = DefaultContractStateDeserializer;
    let did_doc = deserializer.deserialize(&did, &state).unwrap();

    assert!(did_doc.context.is_empty());
    assert_eq!(did_doc.id.to_string(), DID);

    let verification_method_0 = &did_doc.verification_method[0];
    assert_eq!(verification_method_0.r#type, "JsonWebKey2020");
    assert_eq!(verification_method_0.controller, DID);
}

#[cfg(feature = "js-cli")]
#[test]
fn test_midnight_serde_cli() {
    use midnight_did_serde::CliContractStateDeserializer;

    let did = MidnightDid::from_str(DID).unwrap();
    let state = ContractState::from_str(CONTRACT_STATE).unwrap();
    let deserializer = CliContractStateDeserializer::new(CLI_PATH);
    let did_doc = deserializer.deserialize(&did, &state).unwrap();

    assert!(did_doc.context.is_empty());
    assert_eq!(did_doc.id.to_string(), DID);

    let verification_method_0 = &did_doc.verification_method[0];
    assert_eq!(verification_method_0.r#type, "JsonWebKey"); // FIXME: this doesn't look like it is registered
    assert_eq!(verification_method_0.controller, DID);
}
